-- Phase 3 read-only full-contract verification; dependency checks match preflight.
SET @schema_name := 'alrowad_uni_rust';
SELECT COUNT(*) INTO @dependency_base_tables FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_type='BASE TABLE' AND engine='InnoDB' AND table_name IN ('supplementary_exam_periods','supplementary_exam_period_events','supplementary_exam_offerings','supplementary_exam_offering_sources','supplementary_exam_offering_events','student_course_registrations','registration_statuses','student_course_results','result_statuses','grade_components','student_grade_components','grade_part_approvals','grade_approvals','approval_statuses','grading_policies','users','roles','permissions','role_permissions','system_modules');
SELECT COUNT(*) INTO @phase_columns FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND (table_name='supplementary_exam_periods' AND column_name IN ('supplementary_exam_period_id','academic_year_id','semester_id','period_name','start_date','end_date','status','is_active','opened_by_user_id','opened_at','decision_note','created_at','updated_at') OR table_name='supplementary_exam_period_events' AND column_name IN ('supplementary_exam_period_event_id','supplementary_exam_period_id','event_type','from_status','to_status','actor_user_id','notes','created_at') OR table_name='supplementary_exam_offerings' AND column_name IN ('supplementary_exam_offering_id','supplementary_exam_period_id','academic_program_id','course_id','status','opened_by_user_id','opened_at','closed_by_user_id','closed_at','created_at','updated_at') OR table_name='supplementary_exam_offering_sources' AND column_name IN ('supplementary_exam_offering_source_id','supplementary_exam_offering_id','course_offering_id','created_at') OR table_name='supplementary_exam_offering_events' AND column_name IN ('supplementary_exam_offering_event_id','supplementary_exam_offering_id','event_type','from_status','to_status','actor_user_id','notes','created_at'));
SELECT COUNT(*) INTO @phase_primary_ai FROM information_schema.columns c JOIN information_schema.statistics s ON s.table_schema=c.table_schema AND s.table_name=c.table_name AND s.column_name=c.column_name AND s.index_name='PRIMARY' WHERE c.table_schema='alrowad_uni_rust' AND c.extra LIKE '%auto_increment%' AND c.column_name IN ('supplementary_exam_period_id','supplementary_exam_period_event_id','supplementary_exam_offering_id','supplementary_exam_offering_source_id','supplementary_exam_offering_event_id');
SELECT COUNT(*) INTO @phase_fk_semantics FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND referenced_table_schema='alrowad_uni_rust' AND ((table_name='supplementary_exam_periods' AND column_name='academic_year_id' AND referenced_table_name='academic_years' AND referenced_column_name='academic_year_id') OR (table_name='supplementary_exam_periods' AND column_name='semester_id' AND referenced_table_name='semesters' AND referenced_column_name='semester_id') OR (table_name='supplementary_exam_period_events' AND column_name='supplementary_exam_period_id' AND referenced_table_name='supplementary_exam_periods') OR (table_name='supplementary_exam_period_events' AND column_name='actor_user_id' AND referenced_table_name='users') OR (table_name='supplementary_exam_offerings' AND column_name='supplementary_exam_period_id' AND referenced_table_name='supplementary_exam_periods') OR (table_name='supplementary_exam_offerings' AND column_name='academic_program_id' AND referenced_table_name='academic_programs') OR (table_name='supplementary_exam_offerings' AND column_name='course_id' AND referenced_table_name='courses') OR (table_name='supplementary_exam_offerings' AND column_name IN ('opened_by_user_id','closed_by_user_id') AND referenced_table_name='users') OR (table_name='supplementary_exam_offering_sources' AND column_name='supplementary_exam_offering_id' AND referenced_table_name='supplementary_exam_offerings') OR (table_name='supplementary_exam_offering_sources' AND column_name='course_offering_id' AND referenced_table_name='course_offerings') OR (table_name='supplementary_exam_offering_events' AND column_name='supplementary_exam_offering_id' AND referenced_table_name='supplementary_exam_offerings') OR (table_name='supplementary_exam_offering_events' AND column_name='actor_user_id' AND referenced_table_name='users'));
SELECT COUNT(*) INTO @phase_semantic_uniques FROM (SELECT table_name,index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND non_unique=0 GROUP BY table_name,index_name) x WHERE (table_name='supplementary_exam_periods' AND cols='academic_year_id,semester_id') OR (table_name='supplementary_exam_offerings' AND cols='supplementary_exam_period_id,academic_program_id,course_id') OR (table_name='supplementary_exam_offering_sources' AND cols='supplementary_exam_offering_id,course_offering_id');
SELECT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_period_events' AND column_name='supplementary_exam_period_id' AND seq_in_index=1) INTO @p1_event_parent_index_ok;
SELECT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_period_events' AND column_name='actor_user_id' AND seq_in_index=1) INTO @p1_event_actor_index_ok;
SELECT EXISTS(SELECT 1 FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_period_events' GROUP BY index_name) indexes WHERE cols LIKE 'event_type,to_status%') INTO @p1_event_lookup_index_ok;
SELECT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_offering_events' AND column_name='supplementary_exam_offering_id' AND seq_in_index=1) INTO @p2_event_parent_index_ok;
SELECT EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_offering_events' AND column_name='actor_user_id' AND seq_in_index=1) INTO @p2_event_actor_index_ok;
SELECT EXISTS(SELECT 1 FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_offering_events' GROUP BY index_name) indexes WHERE cols LIKE 'event_type,to_status%') INTO @p2_event_lookup_index_ok;
SET @phase2_event_indexes_ready := @p1_event_parent_index_ok=1 AND @p1_event_actor_index_ok=1 AND @p1_event_lookup_index_ok=1 AND @p2_event_parent_index_ok=1 AND @p2_event_actor_index_ok=1 AND @p2_event_lookup_index_ok=1;
SET @sql := IF(@dependency_base_tables=20,'SELECT COUNT(*) INTO @dependency_rbac FROM `alrowad_uni_rust`.`permissions` p JOIN `alrowad_uni_rust`.`role_permissions` rp ON rp.permission_id=p.permission_id JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id WHERE p.is_active=1 AND ((p.permission_code=''supplementary_exams.periods.view'' AND r.role_code IN (''dean'',''vice_president_scientific'')) OR (p.permission_code=''supplementary_exams.periods.decide'' AND r.role_code=''vice_president_scientific'') OR (p.permission_code IN (''supplementary_exams.offerings.view'',''supplementary_exams.offerings.manage'') AND r.role_code=''dean''))','SET @dependency_rbac=0'); PREPARE dependency_stmt FROM @sql; EXECUTE dependency_stmt; DEALLOCATE PREPARE dependency_stmt;
SET @sql := IF(@dependency_base_tables=20,'SELECT COUNT(*) INTO @status_contract FROM (SELECT status_code FROM `alrowad_uni_rust`.`registration_statuses` WHERE status_code IN (''registered'',''completed'') UNION ALL SELECT status_code FROM `alrowad_uni_rust`.`result_statuses` WHERE status_code IN (''failed'',''passed'',''deprived'') UNION ALL SELECT status_code FROM `alrowad_uni_rust`.`approval_statuses` WHERE status_code=''approved'') required_statuses','SET @status_contract=0'); PREPARE status_stmt FROM @sql; EXECUTE status_stmt; DEALLOCATE PREPARE status_stmt;
SET @sql := IF(@dependency_base_tables=20,'SELECT COUNT(*) INTO @grade_policy_contract FROM `alrowad_uni_rust`.`grading_policies` WHERE is_active=1 AND is_default=1 AND minimum_practical_mark IS NOT NULL','SET @grade_policy_contract=0'); PREPARE policy_stmt FROM @sql; EXECUTE policy_stmt; DEALLOCATE PREPARE policy_stmt;
SET @sql := IF(@dependency_base_tables=20,'SELECT COUNT(*) INTO @exam_module_contract FROM `alrowad_uni_rust`.`system_modules` WHERE module_code=''exams'' AND is_active=1','SET @exam_module_contract=0'); PREPARE module_stmt FROM @sql; EXECUTE module_stmt; DEALLOCATE PREPARE module_stmt;
SET @phase2_ready := @dependency_base_tables=20 AND @phase_columns=44 AND @phase_primary_ai=5 AND @phase_fk_semantics=13 AND @phase_semantic_uniques=3 AND @phase2_event_indexes_ready=1 AND @dependency_rbac=5 AND @status_contract=6 AND @grade_policy_contract=1 AND @exam_module_contract=1;
SELECT COUNT(*) INTO @deferral_exists FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferrals' AND table_type='BASE TABLE';
SELECT COUNT(*) INTO @deferral_contract FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferrals' AND ((column_name='supplementary_exam_theoretical_deferral_id' AND data_type='int' AND is_nullable='NO' AND extra LIKE '%auto_increment%') OR (column_name IN ('supplementary_exam_offering_id','student_course_registration_id','declared_by_user_id') AND data_type='int' AND is_nullable='NO') OR (column_name='cancelled_by_user_id' AND data_type='int' AND is_nullable='YES') OR (column_name='current_slot' AND data_type='tinyint' AND is_nullable='YES') OR (column_name='status' AND data_type='varchar' AND character_maximum_length=16 AND is_nullable='NO') OR (column_name IN ('declared_at','created_at','updated_at') AND data_type IN ('datetime','timestamp') AND is_nullable='NO') OR (column_name IN ('cancelled_at','superseded_at') AND data_type IN ('datetime','timestamp') AND is_nullable='YES') OR (column_name IN ('cancellation_reason','supersede_reason') AND data_type='text' AND is_nullable='YES'));
SELECT COUNT(*) INTO @deferral_fks FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferrals' AND referenced_table_schema='alrowad_uni_rust' AND ((column_name='supplementary_exam_offering_id' AND referenced_table_name='supplementary_exam_offerings' AND referenced_column_name='supplementary_exam_offering_id') OR (column_name='student_course_registration_id' AND referenced_table_name='student_course_registrations' AND referenced_column_name='student_course_registration_id') OR (column_name IN ('declared_by_user_id','cancelled_by_user_id') AND referenced_table_name='users' AND referenced_column_name='user_id'));
SELECT COUNT(*) INTO @deferral_indexes FROM (SELECT index_name,non_unique,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferrals' GROUP BY index_name,non_unique) x WHERE (non_unique=0 AND cols IN ('supplementary_exam_theoretical_deferral_id','supplementary_exam_offering_id,student_course_registration_id','student_course_registration_id,current_slot')) OR cols IN ('declared_by_user_id','cancelled_by_user_id');
SELECT COUNT(*) INTO @deferral_engine FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferrals' AND engine='InnoDB' AND table_comment LIKE '%[phase3-supplementary-exam-eligibility]%';
SET @deferral_state:=IF(@deferral_exists=0,'ABSENT',IF(@deferral_contract=14 AND @deferral_fks=4 AND @deferral_indexes=5 AND @deferral_engine=1,'COMPATIBLE','CONFLICT'));
SELECT COUNT(*) INTO @event_exists FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferral_events' AND table_type='BASE TABLE';
SELECT COUNT(*) INTO @event_contract FROM information_schema.columns WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferral_events' AND ((column_name='supplementary_exam_theoretical_deferral_event_id' AND data_type='int' AND is_nullable='NO' AND extra LIKE '%auto_increment%') OR (column_name IN ('supplementary_exam_theoretical_deferral_id','actor_user_id') AND data_type='int' AND is_nullable='NO') OR (column_name IN ('event_type','to_status') AND data_type='varchar' AND character_maximum_length=16 AND is_nullable='NO') OR (column_name='from_status' AND data_type='varchar' AND character_maximum_length=16 AND is_nullable='YES') OR (column_name='notes' AND data_type='text' AND is_nullable='YES') OR (column_name='created_at' AND data_type IN ('datetime','timestamp') AND is_nullable='NO'));
SELECT COUNT(*) INTO @event_fks FROM information_schema.key_column_usage WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferral_events' AND referenced_table_schema='alrowad_uni_rust' AND ((column_name='supplementary_exam_theoretical_deferral_id' AND referenced_table_name='supplementary_exam_theoretical_deferrals' AND referenced_column_name='supplementary_exam_theoretical_deferral_id') OR (column_name='actor_user_id' AND referenced_table_name='users' AND referenced_column_name='user_id'));
SELECT COUNT(*) INTO @event_indexes FROM (SELECT index_name,non_unique,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferral_events' GROUP BY index_name,non_unique) x WHERE (non_unique=0 AND cols='supplementary_exam_theoretical_deferral_event_id') OR cols IN ('supplementary_exam_theoretical_deferral_id,created_at','actor_user_id');
SELECT COUNT(*) INTO @event_engine FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='supplementary_exam_theoretical_deferral_events' AND engine='InnoDB' AND table_comment LIKE '%[phase3-supplementary-exam-eligibility]%';
SET @event_state:=IF(@event_exists=0,'ABSENT',IF(@event_contract=8 AND @event_fks=2 AND @event_indexes=3 AND @event_engine=1,'COMPATIBLE','CONFLICT'));
SET @rbac_exact:=0;SET @off_matrix:=1;
SET @sql:=IF(@dependency_base_tables=20,'SELECT COUNT(*) INTO @rbac_exact FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE m.module_code=''exams'' AND p.is_active=1 AND ((p.permission_code=''supplementary_exams.eligibility.view'' AND r.role_code IN (''dean'',''registration_officer'',''exam_officer'',''vice_president_scientific'')) OR (p.permission_code=''supplementary_exams.deferrals.self'' AND r.role_code=''student''))','SET @rbac_exact=0');PREPARE verify_rbac_stmt FROM @sql;EXECUTE verify_rbac_stmt;DEALLOCATE PREPARE verify_rbac_stmt;
SET @sql:=IF(@dependency_base_tables=20,'SELECT COUNT(*) INTO @off_matrix FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE (p.permission_code=''supplementary_exams.deferrals.self'' AND r.role_code<>''student'') OR (p.permission_code=''supplementary_exams.eligibility.view'' AND r.role_code NOT IN (''dean'',''registration_officer'',''exam_officer'',''vice_president_scientific''))','SET @off_matrix=1');PREPARE verify_matrix_stmt FROM @sql;EXECUTE verify_matrix_stmt;DEALLOCATE PREPARE verify_matrix_stmt;
SET @invalid_deferrals:=1;SET @orphan_deferrals:=1;SET @duplicate_identity:=1;SET @duplicate_current:=1;SET @orphan_events:=1;
SET @sql:=IF(@deferral_state='COMPATIBLE','SELECT COUNT(*) INTO @invalid_deferrals FROM `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` WHERE (status=''declared'' AND (current_slot IS NULL OR current_slot<>1)) OR (status IN (''cancelled'',''superseded'') AND current_slot IS NOT NULL) OR status NOT IN (''declared'',''cancelled'',''superseded'')','SET @invalid_deferrals=1');PREPARE data_stmt FROM @sql;EXECUTE data_stmt;DEALLOCATE PREPARE data_stmt;
SET @sql:=IF(@deferral_state='COMPATIBLE','SELECT COUNT(*) INTO @orphan_deferrals FROM `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` d LEFT JOIN `alrowad_uni_rust`.`supplementary_exam_offerings` o ON o.supplementary_exam_offering_id=d.supplementary_exam_offering_id LEFT JOIN `alrowad_uni_rust`.`student_course_registrations` r ON r.student_course_registration_id=d.student_course_registration_id LEFT JOIN `alrowad_uni_rust`.`users` u ON u.user_id=d.declared_by_user_id WHERE o.supplementary_exam_offering_id IS NULL OR r.student_course_registration_id IS NULL OR u.user_id IS NULL','SET @orphan_deferrals=1');PREPARE data_stmt FROM @sql;EXECUTE data_stmt;DEALLOCATE PREPARE data_stmt;
SET @sql:=IF(@deferral_state='COMPATIBLE','SELECT COUNT(*) INTO @duplicate_identity FROM (SELECT 1 FROM `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` GROUP BY supplementary_exam_offering_id,student_course_registration_id HAVING COUNT(*)>1) x','SET @duplicate_identity=1');PREPARE data_stmt FROM @sql;EXECUTE data_stmt;DEALLOCATE PREPARE data_stmt;
SET @sql:=IF(@deferral_state='COMPATIBLE','SELECT COUNT(*) INTO @duplicate_current FROM (SELECT 1 FROM `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` WHERE current_slot=1 GROUP BY student_course_registration_id HAVING COUNT(*)>1) x','SET @duplicate_current=1');PREPARE data_stmt FROM @sql;EXECUTE data_stmt;DEALLOCATE PREPARE data_stmt;
SET @sql:=IF(@event_state='COMPATIBLE','SELECT COUNT(*) INTO @orphan_events FROM `alrowad_uni_rust`.`supplementary_exam_theoretical_deferral_events` e LEFT JOIN `alrowad_uni_rust`.`supplementary_exam_theoretical_deferrals` d ON d.supplementary_exam_theoretical_deferral_id=e.supplementary_exam_theoretical_deferral_id LEFT JOIN `alrowad_uni_rust`.`users` u ON u.user_id=e.actor_user_id WHERE d.supplementary_exam_theoretical_deferral_id IS NULL OR u.user_id IS NULL','SET @orphan_events=1');PREPARE data_stmt FROM @sql;EXECUTE data_stmt;DEALLOCATE PREPARE data_stmt;
SET @verify_ok:=@phase2_ready AND @deferral_state='COMPATIBLE' AND @event_state='COMPATIBLE' AND @rbac_exact=5 AND @off_matrix=0 AND @invalid_deferrals=0 AND @orphan_deferrals=0 AND @duplicate_identity=0 AND @duplicate_current=0 AND @orphan_events=0;
SELECT 'OVERALL' AS report_section,IF(@verify_ok,'PASS','FAIL') AS result,IF(NOT @phase2_ready,'PHASE2_NOT_DEPLOYED',IF(@deferral_state<>'COMPATIBLE' OR @event_state<>'COMPATIBLE','PHASE3_SCHEMA_INVALID',IF(@rbac_exact<>5 OR @off_matrix<>0,'RBAC_INVALID',IF(@invalid_deferrals<>0,'DEFERRAL_STATE_INVALID',IF(@orphan_deferrals+@orphan_events<>0,'ORPHAN_DATA','DUPLICATE_DATA'))))) AS blocker_code;
